import{_ as e,o as l,c as t,a5 as r}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"配置","description":"","frontmatter":{"title":"配置","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","附录","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/附录/未分类/配置.md","filePath":"posts/java快速入门/附录/未分类/配置.md"}'),o={name:"posts/java快速入门/附录/未分类/配置.md"};function i(s,a,n,p,d,c){return l(),t("div",null,[...a[0]||(a[0]=[r('<div><p>mybatis-plus:</p><h1 id="mybatis-mapper所对应的xml文件位置-请注意与使用的数据库匹配" tabindex="-1">MyBatis Mapper所对应的XML文件位置，请注意与使用的数据库匹配 <a class="header-anchor" href="#mybatis-mapper所对应的xml文件位置-请注意与使用的数据库匹配" aria-label="Permalink to &quot;MyBatis Mapper所对应的XML文件位置，请注意与使用的数据库匹配&quot;">​</a></h1><h1 id="mapper-locations-classpath-mapper-sqlserver-xml" tabindex="-1">mapper-locations: classpath*:mapper/**/sqlserver/*.xml <a class="header-anchor" href="#mapper-locations-classpath-mapper-sqlserver-xml" aria-label="Permalink to &quot;mapper-locations: classpath*:mapper/**/sqlserver/*.xml&quot;">​</a></h1><p>mapper-locations: classpath*:mapper/<strong>/oracle/<em>.xml,classpath</em>:mapper/</strong>/dm/<em>.xml,classpath</em>:mappers/*.xml global-config:</p><h1 id="关闭mp3-0自带的banner" tabindex="-1">关闭MP3.0自带的banner <a class="header-anchor" href="#关闭mp3-0自带的banner" aria-label="Permalink to &quot;关闭MP3.0自带的banner&quot;">​</a></h1><p>banner: false db-config: #字段策略 0:&quot;忽略判断&quot;,1:&quot;非 NULL 判断&quot;),2:&quot;非空判断&quot;</p><h1 id="ignored-忽略判断-所有字段都更新和插入。" tabindex="-1">IGNORED：“忽略判断”，所有字段都更新和插入。 <a class="header-anchor" href="#ignored-忽略判断-所有字段都更新和插入。" aria-label="Permalink to &quot;IGNORED：“忽略判断”，所有字段都更新和插入。&quot;">​</a></h1><h1 id="not-null-非-null-判断-只更新和插入非null值。" tabindex="-1">NOT_NULL：“非 NULL 判断”，只更新和插入非NULL值。 <a class="header-anchor" href="#not-null-非-null-判断-只更新和插入非null值。" aria-label="Permalink to &quot;NOT_NULL：“非 NULL 判断”，只更新和插入非NULL值。&quot;">​</a></h1><h1 id="not-empty-非空判断-只更新和插入非null值且非空字符串。" tabindex="-1">NOT_EMPTY：“非空判断”， 只更新和插入非NULL值且非空字符串。 <a class="header-anchor" href="#not-empty-非空判断-只更新和插入非null值且非空字符串。" aria-label="Permalink to &quot;NOT_EMPTY：“非空判断”， 只更新和插入非NULL值且非空字符串。&quot;">​</a></h1><h1 id="default-默认的-一般只用于注解里。" tabindex="-1">DEFAULT： 默认的，一般只用于注解里。 <a class="header-anchor" href="#default-默认的-一般只用于注解里。" aria-label="Permalink to &quot;DEFAULT： 默认的，一般只用于注解里。&quot;">​</a></h1><p>insert-strategy: not_null update-strategy: not_null selectStrategy: not_null #数据库大写下划线转换 capital-mode: true</p><h1 id="创建人、创建时间、版本号-是否删除等字段自动填充-默认使用下面实现类。" tabindex="-1">创建人、创建时间、版本号，是否删除等字段自动填充，默认使用下面实现类。 <a class="header-anchor" href="#创建人、创建时间、版本号-是否删除等字段自动填充-默认使用下面实现类。" aria-label="Permalink to &quot;创建人、创建时间、版本号，是否删除等字段自动填充，默认使用下面实现类。&quot;">​</a></h1><h1 id="若不满足业务需求-可实现metaobjecthandler接口进行自定义填充" tabindex="-1">若不满足业务需求，可实现MetaObjectHandler接口进行自定义填充 <a class="header-anchor" href="#若不满足业务需求-可实现metaobjecthandler接口进行自定义填充" aria-label="Permalink to &quot;若不满足业务需求，可实现MetaObjectHandler接口进行自定义填充&quot;">​</a></h1><p>meta-object-handler: com.aoip.orm.mybatis.handler.ModelMetaObjectHandler logic-delete-field: delFlag logic-delete-value: 1 logic-not-delete-value: 0 configuration: #开启驼峰功能 map-underscore-to-camel-case: true jdbc-type-for-null: &#39;null&#39;</p><h1 id="mysql-oracle-dm-等-请注意与使用的数据库匹配" tabindex="-1">mysql, oracle, dm 等，请注意与使用的数据库匹配 <a class="header-anchor" href="#mysql-oracle-dm-等-请注意与使用的数据库匹配" aria-label="Permalink to &quot;mysql, oracle, dm 等，请注意与使用的数据库匹配&quot;">​</a></h1><p>database-id: dm #log-impl: org.apache.ibatis.logging.log4j2.Log4j2Impl log-impl: org.apache.ibatis.logging.stdout.StdOutImpl 这是一个针对MyBatis-Plus的配置，MyBatis-Plus是MyBatis的增强工具，主要通过增加一些实用功能来简化MyBatis的操作。下面我会逐个解释这个配置中的各个部分：</p><ol><li>mapper-locations: 这是配置mapper XML文件的位置。在这里，配置了3个位置，分别对应oracle数据库的mapper，达梦数据库的mapper以及通用的mapper。MyBatis会在这些位置找到对应的XML文件，并将它们加载到应用中。</li><li>global-config: 这是全局配置，影响所有的mapper。</li><li>banner: 关闭MyBatis Plus的启动banner。</li><li>db-config: 数据库配置项，针对数据库操作的配置。</li><li>insert-strategy, update-strategy, selectStrategy: 字段策略，定义了插入、更新、选择时的字段策略，可选的值有IGNORED、NOT_NULL、NOT_EMPTY、DEFAULT，对应的策略分别是“忽略判断”、“非NULL判断”、“非空判断”和“默认策略”。</li><li>capital-mode: 是否启用大写下划线模式，如果启用，MyBatis Plus会将数据库表和字段名映射为大写并用下划线分隔。</li><li>meta-object-handler: 自动填充处理器，定义了自动填充创建人、创建时间、版本号以及是否删除等字段的实现类。</li><li>logic-delete-field: 逻辑删除字段，定义了用于标记记录是否被删除的字段名。</li><li>logic-delete-value and logic-not-delete-value: 逻辑删除和未删除的标记值，分别是1和0。</li><li>configuration: 这是MyBatis的核心配置，它包含了很多关于MyBatis行为的配置项。</li><li>map-underscore-to-camel-case: 是否启用驼峰命名法，如果启用，MyBatis会将数据库中的下划线命名方式映射为Java的驼峰命名方式。</li><li>jdbc-type-for-null: 定义了将null值映射到哪种JDBC类型。</li><li>database-id: 数据库标识符，这用于加载对应数据库的SQL映射语句。</li><li>log-impl: 日志实现，定义了MyBatis使用的日志实现类，这里配置的是将日志输出到标准输出。</li></ol><p>这个配置中包含了许多高级功能，例如字段策略、逻辑删除、自动填充等，它们都是MyBatis Plus为了简化MyBatis操作而提供的增强功能。这些功能在大多数应用中都非常有用，可以大大提高开发效率。</p></div>',1)])])}const h=e(o,[["render",i]]);export{u as __pageData,h as default};
